const ui={selectedOrders:[],orderSupplier:'',orderSort:'default',orderList:'active',view:'overview',orderId:null,tab:'overview',search:'',status:'',category:'',page:1,layout:'table',masterTab:'bases',plmTab:'products',shippingTab:'tracking',modal:null,data:{},draft:null,payment:null,importRows:null,importFile:null,trackingRows:null,trackingFile:null,rateRows:null,rateFile:null,mobile:false,revision:null};
const paths={leaf:'M19 4C11 2 4 7 5 13a6 6 0 0 0 6 5c6 0 9-6 8-14ZM4 20l10-10',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',orders:'M8 3h8l2 3h3v15H3V6h3l2-3Zm0 0v5h8V3M7 12h10M7 16h7',check:'m5 12 4 4L19 6',clock:'M12 8v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',box:'m3 7 9-4 9 4v10l-9 4-9-4V7Zm0 0 9 4 9-4M12 11v10M7 5l9 4',ship:'M5 11V5h14v6M8 5V2h8v3M3 12l9-3 9 3-3 7H6l-3-7ZM2 21q3-2 5 0 3-2 5 0 3-2 5 0 2-2 5 0',money:'M3 5h18v14H3zM7 9v6M17 9v6M14 12a2 2 0 1 1-4 0 2 2 0 0 1 4 0',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3M13 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0M22 21v-3a4 4 0 0 0-3-4M18 2a4 4 0 0 1 0 8',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3h6l1 3 3 1 2 4-2 3-1 4-3 3H9l-3-3-1-4-2-3 2-4 3-1 1-3',history:'M3 11a9 9 0 1 1 2 7M3 3v8h8M12 7v6l4 2',alert:'m12 3 10 18H2L12 3ZM12 9v5M12 17v1',arrow:'M5 12h14m-5-5 5 5-5 5',chevron:'m9 5 7 7-7 7',plus:'M12 5v14M5 12h14',search:'M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0M15 15l6 6',bell:'M6 8a6 6 0 0 1 12 0v6l2 3H4l2-3V8ZM9 21h6',file:'M14 2H4v20h16V8l-6-6Zm0 0v6h6M8 12h8M8 16h6',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5',close:'m6 6 12 12M6 18 18 6',calendar:'M3 5h18v16H3V5ZM7 2v6M17 2v6M3 11h18',print:'M6 9V2h12v7M6 17H3V9h18v8h-3M6 14h12v8H6z',lock:'M5 11h14v11H5zM8 11V6a4 4 0 0 1 8 0v5',edit:'m15 3 6 6-12 12H3v-6L15 3ZM12 6l6 6',external:'M14 3h7v7M10 14 21 3M10 3H3v18h18v-7',menu:'M3 6h18M3 12h18M3 18h18',info:'M12 8v1M12 12v5M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0'};
const icon=(n,size=16)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.file}"/></svg>`;
const attrs=o=>Object.entries(o||{}).map(([k,v])=>`data-${k}="${esc(v)}"`).join(' ');
const button=(label,action,data={},kind='',ico='')=>`<button type="button" class="button ${kind}" data-action="${action}" ${attrs(data)}>${ico?icon(ico,14):''}${label}</button>`;
const badge=(label,tone='')=>`<span class="badge ${tone}">${esc(label)}</span>`;
const sb=o=>o.deletedAt?badge('Deleted','red'):badge(STATUS_LABELS[orderStatus(o)],['IN_TRANSIT','PARTIAL_ARRIVAL'].includes(orderStatus(o))?'blue':['PORT_ARRIVED','IN_PRODUCTION','READY_FOR_PRODUCTION'].includes(orderStatus(o))?'green':o.status==='DRAFT'?'dark':'amber');
const dt=d=>d?new Date(String(d).slice(0,10)+'T12:00:00').toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}):'Not set';
const sd=d=>d?new Date(String(d).slice(0,10)+'T12:00:00').toLocaleDateString('en-GB',{day:'2-digit',month:'short'}):'—';
const isoWeekCode=(d=new Date())=>{const x=new Date(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate()));x.setUTCDate(x.getUTCDate()+4-(x.getUTCDay()||7));const y=new Date(Date.UTC(x.getUTCFullYear(),0,1));const w=Math.ceil((((x-y)/86400000)+1)/7);return x.getUTCFullYear()+'-W'+String(w).padStart(2,'0');};
const kv=(label,value)=>`<div><div class="kv-label">${esc(label)}</div><div class="kv-value">${value}</div></div>`;
const empty=(title,body='',ico='box')=>`<div class="empty">${icon(ico,26)}<h3>${esc(title)}</h3>${esc(body)}</div>`;
const note=(s,kind='')=>`<div class="note-box ${kind}">${s}</div>`;
const ph=(title,sub='',act='')=>`<div class="panel-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${act}</div>`;
const head=(eyebrow,title,sub,actions='')=>`<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="head-actions">${actions}</div></div>`;
const kpi=(l,v,foot,ico='box',red=false)=>`<div class="kpi ${red?'red':''}"><div class="kpi-top"><span>${l}</span><span class="kpi-icon">${icon(ico,15)}</span></div><div class="kpi-value">${v}</div><div class="kpi-foot">${foot}</div></div>`;
const recordOrders=()=>state.orders.filter(o=>scopeAllowed(user,o.scope));
const visibleOrders=()=>recordOrders().filter(o=>!o.deletedAt);
const getOrder=id=>recordOrders().find(o=>o.id===id);
const vendor=o=>state.vendors.find(v=>v.id===o.vendorId);
const owner=id=>state.users.find(u=>u.id===id)?.name||'Unassigned';
const allFlags=()=>visibleOrders().flatMap(o=>flagsFor(state,o)).sort((a,b)=>(a.level==='critical'?0:1)-(b.level==='critical'?0:1));
const orderSortOptions=[['default','Original order'],['supplier-asc','Supplier: A to Z'],['supplier-desc','Supplier: Z to A'],['serial-asc','S.No.: smallest to largest'],['serial-desc','S.No.: largest to smallest'],['number-asc','PO number: A to Z'],['number-desc','PO number: Z to A']];
const orderCollator=new Intl.Collator('en',{numeric:true,sensitivity:'base'});
const pipelineOrders=()=>ui.view==='orders'&&user.role==='ADMIN'&&ui.orderList==='deleted'?recordOrders().filter(o=>o.deletedAt):visibleOrders();
function filteredOrders(){const rows=pipelineOrders().filter(o=>(!ui.orderSupplier||o.vendorId===ui.orderSupplier)&&(!ui.status||orderStatus(o)===ui.status)&&(!ui.search||[String(o.serialNumber),o.number,vendor(o)?.name,vendor(o)?.code,...o.lines.map(l=>l.code)].join(' ').toLowerCase().includes(ui.search.toLowerCase())));if(ui.orderSort==='default')return rows;const [field,direction]=ui.orderSort.split('-'),factor=direction==='desc'?-1:1;const value=o=>field==='serial'?o.serialNumber:field==='supplier'?vendor(o)?.name:o.number;return rows.sort((a,b)=>{const av=value(a),bv=value(b),am=av==null||av==='',bm=bv==null||bv==='';if(am!==bm)return am?1:-1;const result=field==='serial'?Number(av)-Number(bv):orderCollator.compare(String(av||''),String(bv||''));return factor*result||(a.serialNumber||0)-(b.serialNumber||0)||orderCollator.compare(a.id,b.id);});}
function orderSortHeader(field,label){const active=ui.orderSort.startsWith(field+'-'),descending=ui.orderSort===field+'-desc';return '<th aria-sort="'+(active?(descending?'descending':'ascending'):'none')+'"><button type="button" class="button small ghost" data-action="sort-orders" data-field="'+field+'" aria-label="Sort by '+esc(label)+'">'+esc(label)+' <span aria-hidden="true">'+(active?(descending?'&#8595;':'&#8593;'):'&#8597;')+'</span></button></th>';}
function orderFilterControls(){const ids=new Set(pipelineOrders().map(o=>o.vendorId)),suppliers=state.vendors.filter(v=>ids.has(v.id)).sort((a,b)=>orderCollator.compare(a.name,b.name)||orderCollator.compare(a.code,b.code));return '<select id="order-supplier" aria-label="Filter by supplier"><option value="">All suppliers</option>'+suppliers.map(v=>'<option value="'+esc(v.id)+'" '+(ui.orderSupplier===v.id?'selected':'')+'>'+esc(v.name)+' / '+esc(v.code)+'</option>').join('')+'</select><select id="order-sort" aria-label="Sort orders">'+orderSortOptions.map(([value,label])=>'<option value="'+value+'" '+(ui.orderSort===value?'selected':'')+'>'+label+'</option>').join('')+'</select>'+button('Reset view','reset-order-view',{},'small ghost');}
async function api(path,options={}){const r=await fetch('/api'+path,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...(csrf?{'X-CSRF-Token':csrf}:{}),...options.headers}});const data=await r.json();if(!r.ok)throw new Error(data.error||'Request failed');return data;}
function persist(s){try{localStorage.setItem(STORE,JSON.stringify(s));}catch{throw new Error('Browser storage is full or unavailable. Export a backup; the change was not saved.');}}
function toast(s,error=false){clearTimeout(timer);$('#toast-root').innerHTML=`<div class="toast ${error?'error':''}" role="status">${icon(error?'alert':'check',16)}<span>${esc(s)}</span></div>`;timer=setTimeout(()=>$('#toast-root').innerHTML='',6500);}
async function command(type,payload,{close=true,message='Saved with visible history.'}={}){if(busy)return;busy=true;const submit=$('#dialog-form [type=submit]');if(submit)submit.disabled=true;try{let result;if(sandbox){const r=execute(state,{type,payload},user);persist(r.state);state=r.state;user=state.users.find(u=>u.id===user.id);result=r.result;}else{const r=await api('/commands',{method:'POST',body:JSON.stringify({type,payload,expectedRevision:state.revision})});state=r.state;user=state.users.find(u=>u.id===user.id);result=r.result;}if(close)closeModal();render();toast(message);return result;}catch(e){showError(e.message);return null;}finally{busy=false;if(submit)submit.disabled=false;}}
function showError(s){const e=$('#modal-error');if(e){e.textContent=s;e.classList.add('visible');e.scrollIntoView({block:'nearest'});}else toast(s,true);}
function navigate(view){closeModal();ui.mobile=false;location.hash='#/'+view;route();}
function route(){const p=(location.hash||'#/overview').replace(/^#\/?/,'').split('/');ui.view=p[0]||'overview';ui.orderId=p[1]||null;ui.search='';ui.status='';ui.page=1;ui.selectedOrders=[];ui.orderList='active';ui.orderSupplier='';ui.orderSort='default';render();if(ui.view==='settings'&&!sandbox&&user.role==='ADMIN')loadUserAccounts();}
async function start(){if(sandbox){try{state=JSON.parse(localStorage.getItem(STORE));if(state?.schemaVersion!==SCHEMA_VERSION)state=null;}catch{}state=state||createCleanSeed();if(ensureOrderSerials(state)){state.revision++;persist(state);}let saved;try{saved=localStorage.getItem(STORE+'-user');}catch{}user=state.users.find(u=>u.id===saved)||state.users[1]||state.users[0];}else{try{const r=await api('/bootstrap');state=r.state;user=r.user;csrf=r.csrf;}catch{return loginView();}}route();}
function demoStrip(){return `<div class="demo-strip">${icon('info',14)}<span>${sandbox?'Clean test workspace: final Vendor Master + 129 Base Item Codes + generated GJ/KD/TT ERP Item Codes + filtered base-product price lists + historical freight benchmarks are loaded. No demo POs, payments, shipments or complaints are preloaded.':'Local pilot only. PLM is active in this build; live VMS synchronization and ERP connections are not enabled.'}</span><a href="#/versions">Build details ${icon('arrow',12)}</a></div>`;}
function sidebar(){const nav=(v,l,ic,n='')=>`<button class="nav-link ${ui.view===v||(v==='orders'&&ui.view==='order')||(v==='plm'&&ui.view==='product')?'active':''}" data-action="nav" data-to="${v}">${icon(ic,16)}<span>${l}</span>${n!==''?`<span class="nav-count">${n}</span>`:''}</button>`;return `<aside class="sidebar ${ui.mobile?'open':''}"><div class="brand brand-logo-block"><div class="brand-logo-shell"><img class="brand-logo" src="${FARMING_HUB_LOGO}" alt="Farming Hub"></div><div class="brand-sub">Purchase management</div></div><div class="nav-label">Workspace</div>${nav('overview','Overview','grid')}<div class="nav-label">LAE Import</div>${nav('orders','Order pipeline','orders',visibleOrders().filter(o=>!['DRAFT','PORT_ARRIVED','SHORT_CLOSED'].includes(orderStatus(o))).length)}${nav('tasks','Tasks & follow-ups','clock')}${nav('payments','Payments','money')}${nav('shipments','Shipping & freight','ship')}${nav('documents','QC & documents','file')}<div class="nav-label">Libraries</div>${nav('vendors','Vendor master','users')}${nav('items','Item master','orders')}${nav('prices','Supplier price lists','money')}${nav('plm','Product Lifecycle (PLM)','box')}<div class="sidebar-bottom">${nav('settings','Users & settings','settings')}${nav('versions','Version & edit log','history')}<div class="sidebar-note"><b>${sandbox?'Clean browser workspace':'Local pilot workspace'}</b>Controlled purchasing for modern farm mechanization. Planning and ERP connect later.</div><div class="version-mini"><span>v${APP_VERSION}</span><span>LAE · Import</span></div></div></aside>`;}
function topbar(){const titles={overview:'Overview',orders:'Order pipeline',order:getOrder(ui.orderId)?.number||'Order',tasks:'Tasks & follow-ups',payments:'Payments',shipments:'Shipping & freight',documents:'QC & documents',vendors:'Vendor master',prices:'Supplier price lists',plm:'Product Lifecycle',product:'PLM product',items:'Item master',settings:'Users & settings',versions:'Version & edit log'};return `<header class="topbar"><div class="flex"><button class="icon-button mobile-toggle" data-action="mobile" aria-label="Open navigation">${icon('menu')}</button><div class="breadcrumb">Purchase Management ${icon('chevron',11)} <b>${esc(titles[ui.view]||'Roadmap')}</b></div></div><div class="top-tools"><div class="search-top">${icon('search',13)}<input id="global-search" placeholder="Find a PO or brand SKU…" aria-label="Find a PO or brand SKU"><small>↵</small></div><button class="icon-button" data-action="nav" data-to="tasks" aria-label="View due tasks">${icon('bell')}</button><div class="account"><span class="avatar">${esc(user.name.split(' ').slice(0,2).map(x=>x[0]).join(''))}</span><div>${sandbox?`<select id="demo-role" aria-label="Review role">${state.users.map(u=>`<option value="${u.id}" ${u.id===user.id?'selected':''}>${esc(u.name.replace('Demo ',''))}</option>`).join('')}</select>`:`<span class="small strong">${esc(user.name)}</span>`}<small>${sandbox?'Review role · not authentication':esc(user.role)}</small></div>${sandbox?'':button('Sign out','logout',{},'small ghost')}</div></div></header>`;}
function render(){if(!state||!user)return;const views={overview:overviewView,orders:ordersView,order:orderView,tasks:tasksView,payments:paymentsView,shipments:shipmentsView,documents:documentsView,vendors:vendorsView,prices:priceListsView,plm:plmView,product:productView,items:itemsView,settings:settingsView,versions:versionsView,roadmap:roadmapView};$('#app').innerHTML=sidebar()+`<div class="workspace">${topbar()}<main class="content">${(views[ui.view]||overviewView)()}<div class="footer-note"><span>Farming Hub Purchase Management · ${sandbox?'isolated browser review':'local authenticated pilot'}</span><span>v${APP_VERSION} · ${state.demo?'Sample approvals and payments are illustrative':'Manual tracking, no bank / inventory posting'}</span></div></main></div>`;}
function flagList(flags,max=6){return flags.slice(0,max).map(f=>`<div class="flag-row"><div class="flag-icon ${f.level==='warning'?'warning':''}">${icon('alert',14)}</div><div class="flag-body"><div class="flag-title">${esc(f.label)}</div><div class="flag-meta">${esc(f.detail)}</div><a href="#/order/${f.orderId}">${esc(getOrder(f.orderId)?.number)} · ${esc(f.owner)}</a></div><button class="icon-button" data-action="open-order" data-id="${f.orderId}" aria-label="Open flagged order">${icon('chevron',12)}</button></div>`).join('')||empty('No current flags','Dates and open work are within configured thresholds.','check');}
function overviewView(){const os=visibleOrders(),active=os.filter(o=>!['DRAFT','PORT_ARRIVED','SHORT_CLOSED'].includes(orderStatus(o))),production=os.filter(o=>orderStatus(o)==='IN_PRODUCTION'),transit=os.flatMap(o=>o.shipments.filter(s=>s.actualDeparture&&!s.actualArrival)),flags=allFlags(),urgent=flags.filter(f=>f.level==='critical'),arrivals=os.flatMap(o=>o.shipments.filter(s=>!s.actualArrival&&s.status!=='CANCELLED').map(s=>({o,s}))).sort((a,b)=>a.s.eta.localeCompare(b.s.eta));const groups=[['Approval, PI & sample',['PENDING_APPROVAL','AWAITING_PI','SAMPLE_REQUIRED','READY_FOR_PRODUCTION']],['In production',['IN_PRODUCTION']],['Shipment readiness',['READY_TO_SHIP']],['In transit / partial',['IN_TRANSIT','PARTIAL_ARRIVAL']],['Port arrived',['PORT_ARRIVED']]];return head('Purchase workspace','Every order. One clear view.','A division-wise view of commitments, upcoming arrivals and the work that needs attention.',button('Export pipeline','export-orders',{},'','download')+(canCreate(user)?button('Create purchase order','new-order',{},'primary','plus'):''))+demoStrip()+`<div class="scope-row">${SCOPES.filter(s=>scopeAllowed(user,s)).map(s=>`<button class="scope-card ${s==='LAE_IMPORT'?'active':''}" data-action="nav" data-to="${s==='LAE_IMPORT'?'orders':'roadmap'}"><div><div class="title">${SCOPE_LABELS[s]}</div><div class="desc">${s==='LAE_IMPORT'?'Active workflow · manual PO entry':'Planned · not implemented'}</div></div>${s==='LAE_IMPORT'?`<span class="value">${active.length}</span>`:icon('lock',15)}</button>`).join('')}</div><div class="kpi-grid">${kpi('Active purchase orders',active.length,'LAE Import · excluding drafts','orders')}${kpi('In production',production.length,'Milestones, not percentage estimates','box')}${kpi('Containers in transit',transit.length,'Actual departure recorded','ship')}${kpi('Critical flags',urgent.length,`${new Set(urgent.map(f=>f.orderId)).size} orders need attention`,'alert',true)}</div><div class="grid-main"><div class="panel">${ph('Purchase pipeline','Current stage of every visible order',badge('LAE · Import','green'))}<div class="pipeline-bars">${groups.map(([l,ss])=>{const n=os.filter(o=>ss.includes(orderStatus(o))).length;return `<div class="bar-line"><span>${l}</span><div class="bar"><i style="width:${Math.max(1,n/Math.max(1,os.length)*100)}%"></i></div><b>${n}</b></div>`;}).join('')}</div><div class="panel-footer">${os.length} orders · ${os.filter(o=>o.status==='DRAFT').length} draft · Physical arrival does not settle the payment balance.</div></div><div class="panel">${ph('Attention required',`${urgent.length} critical · ${flags.length-urgent.length} advance warnings`,button('View all','nav',{to:'tasks'},'small ghost','arrow'))}${flagList(flags,3)}</div></div><div class="panel">${ph('Upcoming port arrivals','Latest reported ETA compared with the original baseline',button('All shipments','nav',{to:'shipments'},'small ghost','arrow'))}<div class="table-wrap"><table><thead><tr><th>Purchase order</th><th>Container / shipment</th><th>Route</th><th>Current ETA</th><th>Baseline change</th><th>Status</th></tr></thead><tbody>${arrivals.slice(0,5).map(({o,s})=>`<tr class="row-click" data-action="open-order" data-id="${o.id}"><td><span class="code-link">${esc(o.number)}</span><div class="sub">${esc(o.lines[0].code)} · ${s.lines.reduce((n,l)=>n+l.quantity,0)} units</div></td><td><span class="mono">${esc(s.container||'Awaiting container')}</span><div class="sub">${esc(s.number)}</div></td><td>${esc(s.origin)} → ${esc(s.destination)}</td><td class="strong">${dt(s.eta)}</td><td>${badge(s.eta===s.baselineEta?'On baseline':daysBetween(s.baselineEta,s.eta)+' days',s.eta===s.baselineEta?'green':'amber')}</td><td>${badge(s.actualDeparture?'In transit':'Planned',s.actualDeparture?'blue':'dark')}</td></tr>`).join('')||`<tr><td colspan="6">${empty('No upcoming shipments')}</td></tr>`}</tbody></table></div></div>`;}
function pageButtons(total,per=12){const pages=Math.max(1,Math.ceil(total/per));return `<div class="pagination"><span>${total?`${(ui.page-1)*per+1}–${Math.min(total,ui.page*per)} of ${total}`:'0 records'}</span><div class="flex">${ui.page>1?button('Previous','page',{page:ui.page-1},'small'):''}<span>${ui.page} / ${pages}</span>${ui.page<pages?button('Next','page',{page:ui.page+1},'small'):''}</div></div>`;}
function orderRows(os){return os.map(o=>{const f=flagsFor(state,o),q=shipmentTotals(o);return `<tr class="row-click" data-action="open-order" data-id="${o.id}">${user.role==='ADMIN'?`<td><input type="checkbox" data-order-select="${o.id}" aria-label="Select PO ${esc(o.number||o.serialNumber)}" ${ui.selectedOrders.includes(o.id)?'checked':''}></td>`:''}<td class="mono">${o.serialNumber}</td><td><span class="code-link">${esc(o.number||'Unnumbered draft')}</span><div class="sub">Rev ${o.revision} · ${sd(o.createdAt)}</div></td><td><span class="strong">${esc(vendor(o)?.name||'Unknown supplier')}</span><div class="sub">${esc(vendor(o)?.code)}</div><div class="sub">${esc(o.lines.map(l=>l.code).join(', '))}</div></td><td class="right">${q.required}<div class="sub">${q.arrived} port-arrived</div></td><td class="right strong">${formatMoney(orderTotal(o),o.currency)}</td><td>${sb(o)}</td><td>${dt(o.requestedPortDate)}</td><td>${badge(f.some(x=>x.level==='critical')?'Attention needed':f.length?f.length+' warnings':'On track',f.some(x=>x.level==='critical')?'red':f.length?'amber':'green')}</td></tr>`;}).join('');}
