async function backup(){const zip=new JSZip();zip.file('workspace.json',JSON.stringify(state,null,2));let missing=0;for(const f of state.files){try{zip.file('files/'+f.id+'-'+f.name,await getFile(f.id));}catch{missing++;}}zip.file('README.txt',`Farming Hub browser review backup\nSoftware ${APP_VERSION}\nMissing evidence bodies: ${missing}\nNot a backup of live VMS or ERP.\n`);download(await zip.generateAsync({type:'blob'}),'FH_Review_Backup_'+isoDay()+'.zip');toast(missing?`Backup exported; ${missing} evidence body/bodies were unavailable.`:'Review data and evidence exported.');}
function printPO(o){const r=o.revisions[ui.revision??o.revisions.length-1];const snap=r?.snapshot||{number:o.number,vendor:vendor(o),currency:o.currency,incoterm:o.incoterm,requestedPortDate:o.requestedPortDate,paymentTerms:o.paymentTerms,lines:o.lines.map(l=>({...l,specification:approvedSpec(state,l.baseId,l.specId)})),totalMinor:orderTotal(o),notes:o.notes,attachments:[]};$('.print-sheet')?.remove();const el=document.createElement('div');el.className='print-sheet';el.innerHTML=`<div class="print-head"><div><img class="print-logo" src="${FARMING_HUB_LOGO}" alt="Farming Hub"><div class="eyebrow">FARMING HUB PRIVATE LIMITED</div><h1>Purchase Order</h1><p class="subtitle">LAE Import · ${r?'Issued snapshot':'DRAFT — NOT ISSUED'}</p></div><div class="right"><h2>${esc(snap.number||'Draft')}</h2><p>PO Revision ${r?.revision??0}</p><p>${dt(r?.at||o.createdAt)}</p></div></div><div class="kv-grid">${kv('Supplier',esc(snap.vendor?.name)+'<br>'+esc(snap.vendor?.code))}${kv('Currency / trade term',esc(snap.currency)+' · '+esc(snap.incoterm))}${kv('Required port arrival',dt(snap.requestedPortDate))}${kv('Payment terms',esc(snap.paymentTerms.name))}</div><h2>Order lines</h2><table><thead><tr><th>ERP Item Code</th><th>Version</th><th>Qty</th><th>Unit price</th><th>Total</th></tr></thead><tbody>${snap.lines.map(l=>`<tr><td><b>${esc(l.code)}</b><br>${esc(l.name)}</td><td>${esc(l.specification?.version||'Not released')}</td><td>${l.quantity}</td><td>${formatMoney(l.unitPriceMinor,snap.currency)}</td><td>${formatMoney(l.quantity*l.unitPriceMinor,snap.currency)}</td></tr>`).join('')}</tbody></table><h2 class="right">Total ${formatMoney(snap.totalMinor??orderTotal(o),snap.currency)}</h2><h2>Technical requirements annexure</h2>${snap.lines.map(l=>`<div class="print-line"><h3>${esc(l.code)} · ${esc(l.specification?.version||'Unreleased')}</h3><pre>${esc(l.specification?.description||'No approved specification.')}</pre><p><b>Brand packaging / decal requirements:</b> ${esc(l.artworkNotes||'Not supplied')}</p></div>`).join('')}<h2>Issued document manifest</h2><p>${snap.attachments?.length?snap.attachments.map(d=>esc(d.name)+' · '+esc(d.fileId)).join('<br>'):'No additional files attached at the time of this issued snapshot.'}</p><h2>Commercial remarks</h2><pre>${esc(snap.notes||'—')}</pre><p>Issued by: ${esc(r?.actor||'Pending approval')}</p>${state.demo?'<div class="print-warning">DEMONSTRATION ONLY. This is not a real commercial order. Sample products, specifications and approvals are illustrative.</div>':''}`;document.body.append(el);window.print();}
